def _env_int(name: str, default: int) -> int:
    return int(os.environ.get(name, default))


def _env_float(name: str, default: float) -> float:
    return float(os.environ.get(name, default))


# Ladder: (ticks behind the join anchor, contracts). Reward credit halves per
# tick behind the best, so the at-best lot is small (pickoff exposure) and the
# deeper lots carry the size.
def _parse_levels(spec: str) -> List[Tuple[int, int]]:
    out = []
    for part in spec.split(","):
        ticks, size = part.split(":")
        out.append((int(ticks), int(size)))
    if not out or any(t < 0 or s <= 0 for t, s in out):
        raise ValueError(f"bad IMM_LEVELS spec: {spec!r}")
    return out


LEVELS = _parse_levels(os.environ.get("IMM_LEVELS", "0:5,1:10,2:20"))
SIDE_MAX_CONTRACTS = sum(s for _t, s in LEVELS)      # 35 with the default spec
# Ladder placement mode (2026-08-01, post-amendment shape sim v2):
#   offsets — legacy: rungs at fixed tick offsets behind the join anchor.
#   atref   — collapse the side's total size to ONE rung at the book's
#             REFERENCE level (cumulative depth >= target/5): the deepest
#             price that still scores FULL weight under the amended program
#             rules. Same estimated reward as all-at-touch (+/-1% on 90
#             live books), ~half the fill exposure, ~2/3 the collateral.
#             Falls back to the offsets ladder when the book has no
#             reference (too thin) — there, position IS the touch anyway.
LADDER_MODE = os.environ.get("IMM_LADDER_MODE", "offsets").strip().lower()
# Deep-reference size multiplier (Jack 2026-08-01: "the deeper the reference
# point, the larger contract size can be placed — it's much safer"): an
# at-ref rung N ticks behind the touch only fills after the market eats the
# whole band above it, so it carries more size for the same fill risk.
# 1.0 at the touch, +SLOPE per tick of depth, capped at MAX_MULT. Scales the
# atref rung AND the side_max room component; position/event caps and skew
# still bind on top. 0.1/2.0 -> 0.25/3.0 (Jack 2026-08-02 "raise the cap...
# run it through the sim first"): ref_cap_sim on 120 live books — deeper
# curves IMPROVE est-per-unit-fill-risk in every engaged bucket (4-5 ticks:
# 0.104 -> 0.124; 6+ ticks: 1.62 -> 2.21, est $223 -> $318/day on 13 books
# at +4% risk-load). The 0.40/4.0 curve tested even better (2.70, $406/day)
# — step there via env after a day of live fill data.
REF_DEPTH_SLOPE = _env_float("IMM_REF_DEPTH_SLOPE", 0.25)
REF_DEPTH_MAX_MULT = _env_float("IMM_REF_DEPTH_MAX_MULT", 3.0)
# Total-multiplier cap (Jack 2026-08-02): hour mult x ref mult <= this — the
# quiet-hours 2x and deep-ref 3x each claim an independent risk discount and
# their product claimed both at once (worst rung 20x2x3=120). The cap trims
# the REF contribution only (never below 1.0), via capped_ref_mult at every
# sizing site (ladder total, estimator meta, live side rooms). 0 = off.
TOTAL_SIZE_MULT_CAP = _env_float("IMM_TOTAL_SIZE_MULT_CAP", 5.0)
# Requote hysteresis for atref rungs (2026-08-02 audit): full weight is flat
# across the band, so churn on 1-tick touch/ref wiggles buys nothing.
# 1 -> 0 (Jack 2026-08-03: "sticky quotes that dont adjust the quote by 1c is
# making markets like this not earn rewards"). The 1-tick tolerance existed to
# avoid cancel+place churn, but amend-in-place (same day) reprices in ONE call
# with no book gap, so the churn argument is gone — while a rung left 1 tick
# below the reference earns HALF weight until its TTL. Temp already ran 0.
ATREF_PRICE_TOL_TICKS = _env_int("IMM_ATREF_PRICE_TOL", 0)
ATREF_COUNT_TOL_FRAC = _env_float("IMM_ATREF_COUNT_TOL", 0.2)
# Safe-join placement (Jack 2026-08-02, company/econ re-entry): on a tight
# book (spread < MIN_SPREAD ticks) quotes rest at least OFFSET ticks behind
# the touch — an "ample safety net" against informed flow; a wide spread is
# its own net, so >= MIN_SPREAD books join normally. Applied inside
# build_side_ladder (single site: live loop AND estimator inherit).
SAFE_JOIN_OFFSET_TICKS = _env_int("IMM_SAFE_JOIN_OFFSET", 2)
SAFE_JOIN_MIN_SPREAD = _env_int("IMM_SAFE_JOIN_MIN_SPREAD", 5)
# Fast-lane (Jack 2026-08-02): between full cycles, re-quote ONLY fast-lane
# series (KXTEMP — hourly books gap on METAR updates and the ~50s full-cycle
# cadence left rungs ticks behind the reference) every FAST_LANE_SECS of the
# main sleep window. A fast tick is a FILTERED run_cycle: full managed set +
# full resting read (stray-cancel, caps and the diff stay correct), non-fast
# markets skipped at the quote-loop head with their resting orders preserved
# through the diff; universe refresh, accrual integration, bench streaks,
# watchdog, cycle log and counters run on FULL cycles only. 0 = off.
FAST_LANE_SECS = _env_int("IMM_FAST_LANE_SECS", 5)


def ref_depth_mult(anchor: Optional[int], ref_px: Optional[int],
                   book_side: str) -> float:
    """Size multiplier for an at-ref rung by its depth behind the touch.
    1.0 whenever atref is off, inputs are missing, or the reference is at/
    above the anchor (tight book: placement IS the touch)."""
    if LADDER_MODE != "atref" or anchor is None or ref_px is None:
        return 1.0
    depth = (anchor - ref_px) if book_side == "bid" else (ref_px - anchor)
    if depth <= 0:
        return 1.0
    return min(REF_DEPTH_MAX_MULT, 1.0 + REF_DEPTH_SLOPE * depth)


def capped_ref_mult(anchor: Optional[int], ref_px: Optional[int],
                    book_side: str, hour_mult: float = 1.0,
                    series: Optional[str] = None) -> float:
    """ref_depth_mult with the TOTAL-multiplier cap applied: hour_mult (the
    factor already baked into the hour-scaled ladder) x the returned ref
    mult never exceeds TOTAL_SIZE_MULT_CAP. Trims the ref contribution only
    — never below 1.0, so an hour mult alone can still exceed the cap by
    deliberate env choice. THE single accessor for every sizing site.
    `series` (2026-09-05): open-scan members cap the deep-reference lever
    at SCAN_REF_MULT_CAP — an unmeasured family gets the structural safety
    argument for deeper rungs, not the full 3x size that goes with it."""
    m = ref_depth_mult(anchor, ref_px, book_side)
    if TOTAL_SIZE_MULT_CAP > 0 and hour_mult > 0:
        m = min(m, max(1.0, TOTAL_SIZE_MULT_CAP / hour_mult))
    if series is not None and SCAN_REF_MULT_CAP > 0 \
            and series in SCAN_GUARDED_SERIES:
        m = min(m, max(1.0, SCAN_REF_MULT_CAP))
    return m


def clamp_side_max_to_position_cap(side_max_bid: int, side_max_ask: int,
                                   maxpos: float) -> Tuple[int, int]:
    """No ONE side may rest more contracts than the market's whole net
    position cap.

    The cap is enforced when orders are SIZED, against the position as read at
    the start of the cycle — it is not a hard limit at fill time. So the real
    bound is (position last seen) + (whatever a single re-place can carry),
    and when a side ladder is bigger than the cap itself that second term
    dominates.

    Live 2026-08-04, KXTEMPAUSH-26AUG0409-T79.99, cap 50: the bot was long
    +25, so sell room was 50+25=75, trimmed to the ladder's side max of 60
    (20/side x the 3.0 deep-reference multiplier) and it rested 60. 35 filled,
    taking the position to -10, and 28 seconds later — before that fill was
    observed — it re-placed a full 60 sized off the stale +25. That filled
    too: 25 - 35 - 60 = -70 against a 50 cap. The fill-burst breaker would
    have caught the 35-lot move, but IMM_BREAKERS defaults to 0.

    Clamping here does not make the cap hard (only a pre-place position
    re-read would), but it removes the case where ONE order exceeds the whole
    cap, which is what turned a 35-contract surprise into a 20-contract
    breach. Non-temp series are unaffected: 20/side x 3.0 = 60 sits well under
    their 150 cap.

    NOTE the collateral reservation (market_cost) still charges the unclamped
    ref multiplier, so it now over-reserves slightly on clamped markets. That
    is the safe direction and is left alone deliberately."""
    if maxpos <= 0:
        return side_max_bid, side_max_ask
    cap = int(maxpos)
    return min(side_max_bid, cap), min(side_max_ask, cap)


@dataclass(frozen=True)
class SeriesOverride:
    """Per-series overrides of the global quoting spec (user-directed)."""
    levels: Optional[List[Tuple[int, int]]] = None      # ladder shape
    max_position: Optional[float] = None                # net cap per market
    quote_all: bool = False                             # quote EVERY market of the
    #   event, exempt from yield ranking / MAX_MARKETS / collateral budget
    hard_expiry_et: Optional[Tuple[int, int]] = None    # (hour, minute) ET on the
    #   event date — a floor on the cutoff so nothing rests past it
    start_buffer_min: Optional[int] = None              # override the global
    #   EVENT_START_BUFFER_MIN for this series (0 = quote right up to the start)
    pad_to_target: bool = False                         # when a quoted side's total
    #   depth is below the reward target size, add throwaway contracts at the 1c
    #   mark (bid) / 99c mark (ask) to reach it, so the near-touch ladder qualifies
    cutoff_before_event_min: Optional[int] = None       # stop this many minutes
    #   BEFORE the ticker-date midnight (Jack 2026-07-29: rain dailies stop
    #   quoting 6pm ET the day before -> 360). Applied as a min() on top of
    #   whatever the resolver/ticker rule produced.
    cutoff_from_close_min: Optional[int] = None         # cutoff = close_time minus
    #   this many minutes, REPLACING the ticker-date/occurrence rules — for series
    #   whose whole life IS the event (hourly weather markets) and which the
    #   midnight-ET rule would otherwise kill on sight
    event_day_cutoff_et: Optional[Tuple[int, int]] = None  # (hour, minute) ET ON the
    #   event date, replacing the ticker-date MIDNIGHT rule — the only lever here
    #   that moves a cutoff LATER. For day-dated series with no scheduled release
    #   to dodge, where midnight is arbitrary (Treasuries: 7:30am ET, ahead of the
    #   8:30 data). Never overrides an occurrence-based cutoff; clamped to close.
    min_hours_to_close: Optional[float] = None          # override the global
    #   MIN_HOURS_TO_CLOSE screen (hourly markets live less than the 1h default)
    min_est_total: Optional[float] = None               # override the global
    #   MIN_EST_TOTAL_DOLLARS entry/hopeless floor — sub-hour temp windows make
    #   $1 a high bar (Jack 2026-08-02: flanking strikes measured $0.6-0.8)
    atref_price_tol_ticks: Optional[int] = None         # override the global
    #   ATREF_PRICE_TOL_TICKS requote hysteresis. 0 = reprice on ANY reference
    #   move (Jack 2026-08-02 for KXTEMP: hourly books gap on METAR updates and
    #   a 1-tick-behind rung earns half weight; temp is ~24 orders, churn cheap)
    fast_lane: bool = False                             # requote this series on
    #   the FAST_LANE_SECS mini-cycles between full cycles (KXTEMP)
    blackout_et: Optional[Tuple[str, str]] = None       # ("HH:MM","HH:MM") ET
    #   daily window in which the series is NOT quoted and resting orders are
    #   cancelled — for a recurring scheduled data release that reprices the
    #   book (AAA gas/diesel prints, observed 03:18-03:36 ET). Distinct from
    #   `cutoff`, which is a one-time end; a blackout recurs every day and the
    #   market resumes quoting afterwards.
    blackout_weekdays_only: bool = False                # the blackout runs
    #   Mon-Fri ET only (the CPI pilot: 8:30 releases + the Cleveland Fed
    #   nowcast's ~10:00 update are business-day events)
    min_est_per_day: Optional[float] = None             # RATE floor: skip fresh
    #   candidates whose est $/day is below this (re-entry quality bar; on TOP
    #   of the total-accrual payout floor). None/0 = off.
    safe_join: bool = False                             # safety-net placement:
    #   rest >= SAFE_JOIN_OFFSET_TICKS behind the touch unless the bid/ask
    #   spread is >= SAFE_JOIN_MIN_SPREAD ticks (re-entry company/econ)
    release_guard_day: Optional[int] = None             # DATA-MONTH release
    #   guard: cutoff = 00:00 ET on this day of the month AFTER the data month
    #   the market's own title/rules name ("... for September 2026 be above
    #   6%?"), applied as a min() on top of every other rule. For series whose
    #   ticker date is a listing-derived far date that sits AFTER the release
    #   (the Ramp AI Index family). A guarded market whose text carries no
    #   month is stood down, never quoted on the ticker-date fallback.
    pre_cutoff_reduce_only_secs: Optional[int] = None   # override the global
    #   PRE_CUTOFF_REDUCE_ONLY_SECS (default 0 since 2026-08-02 — the window
    #   is removed bot-wide; set >0 here or via env to restore per-series)
    price_min_cents: Optional[int] = None               # per-series order price
    price_max_cents: Optional[int] = None               #   band (else global)
    size_mult: Optional[float] = None                   # FAMILY size multiplier
    #   on the global geometry: ladder rungs, per-market and per-event caps
    #   and the skew knees scale together (the mention x1.5 wire). Sports
    #   ladders / escalators x2 (Jack 2026-09-26). Ignored when `levels` or
    #   `max_position` are hand-tuned (applied_mention_mult returns 1.0).
    pre_event_days: Optional[float] = None              # AWARDS STAND-DOWN
    #   (Jack 2026-09-25 "do not quote within 1 month of when the event
    #   starts"): cutoff = the event's start minus this many days, the start
    #   read by awards_event_start (hand table first, then Kalshi's
    #   occurrence / expected expiration); no usable start -> stood down.
    pre_event_dates_only: bool = False                  # only the hand table
    #   (AWARDS_EVENT_DATES) may supply the start -- for families whose
    #   Kalshi expiration is a Dec 31 placeholder (the Oscars)
    unwind_full_position: bool = False                  # FULL UNWIND: the
    #   side that REDUCES the bot's position may rest the whole position
    #   instead of only its ladder (see unwind_side_sizes)


# Depth-padding (pad_to_target): fill a thin side up to the reward target with
# cheap far-from-touch contracts, rounded up to the nearest PAD_ROUND. 1c bids /
# 99c asks cost ~1c collateral and ~1c max loss each; they earn ~0 (weight
# 0.5^(~47 ticks) ≈ 0) but unlock the near-touch ladder's rewards.
# Pad price history 2026-08-02/03: 1/99 -> 2/98 ("don't place at 1c/99c")
# -> BACK to 1/99 same night (Jack "Set pads back to 1/99"). At 1/99 pads
# sit outside the 2-98 RUNG envelope, so pad-vs-rung price classification
# is unambiguous again; the 5-90 pad_band_ok mid gate still applies.
PAD_BID_CENTS = _env_int("IMM_PAD_BID_CENTS", 1)
PAD_ASK_CENTS = _env_int("IMM_PAD_ASK_CENTS", 99)
# TOUCH band for pads (Jack 2026-09-13: "remove 1000 pads on markets where
# the top of the orderbook is <10c or >90c... i dont want pads to be
# bought"): on top of the 5-90 MID gate, no pad rests on a market whose
# best bid is under PAD_TOUCH_MIN_CENTS or whose best ask is over
# PAD_TOUCH_MAX_CENTS. The mid gate let KXAAAGASDNC-26SEP14-4.0100 pad
# 1,000 contracts at 1c under a 6c/7c book (mid 6.5, inside 5-90): five
# ticks from the touch on a market that settles on one print, a pad like
# that is the first thing a seller hits. Whole market, both sides -- a
# one-sided pad on such a book qualifies nothing worth the fill.
PAD_TOUCH_MIN_CENTS = _env_int("IMM_PAD_TOUCH_MIN", 10)
PAD_TOUCH_MAX_CENTS = _env_int("IMM_PAD_TOUCH_MAX", 90)
PAD_ROUND = _env_int("IMM_PAD_ROUND", 100)
# 5000 -> 800 ("Max do 800") -> 1000 (Jack 2026-08-03 "allow pads to go up
# to 1k"): bounds each pad order's contracts — worst-case ~$10/side at 1c.
# At 1000 a pad can single-handedly satisfy the standard 1000 target when a
# side is completely empty (the 800 cap left near-empty sides unable to
# qualify at all).
PAD_MAX_CONTRACTS = _env_int("IMM_PAD_MAX", 1000)
# A pad must rest AT LEAST this many ticks behind its side's external touch
# (Jack 2026-08-03 "dont pad if 1c is the top of the book, i dont want pads
# to get bought up easily"): a 1c pad under a 1-2c best bid IS the market —
# first in line for any seller. Per-side; mirrored in the estimator.
PAD_MIN_TICKS_BEHIND = _env_int("IMM_PAD_MIN_BEHIND", 2)
# Headroom added on top of the exact gap whenever a pad is needed (Jack
# 2026-08-01: AUG0110-T82.99 yes side padded to exactly ~1000, then external
# retail depth withdrew and the side sat below target — disqualified — until
# the next requote resized. Slack keeps the side qualified through external
# churn between requotes, and damps pad resize churn (hysteresis via
# rounding). ~$3 collateral per pad at 1c/99c.
PAD_SLACK_CONTRACTS = _env_int("IMM_PAD_SLACK", 300)
# GLOBAL since 2026-07-29 (Jack: "some quotes are not earning because there
# are not 1000 orders on that side... fix this systematically — quote how
# many orders are necessary at the very bottom of the orderbook"): every
# quoted market pads its thin sides to the reward target. Pads price at
# 1c/99c deliberately OUTSIDE the 5-90 band — they are qualification depth,
# not quotes; built in _pad_quotes (never through build_side_ladder), so
# the band never clips them, and stood-down markets never reach the pad
# site. The candidate estimator models them too, else thin markets read
# est=0 and die at the floor before a pad could ever rest.
# GLOBAL again (Jack 2026-08-05, same day: "only pad on hourly TEMP markets"
# -> "actually turn pads back on for everything"). The temp-only spell cost the
# NEAR-MISS tail: DUOL/MELI earnings strikes sitting at 584-981 contracts
# against a 1000 target stood down when a 20-420 contract pad at 1c would have
# qualified them.
#
# NOTE THE INTERACTION: the two-sided depth gate in the quote loop is skipped
# for any series that pads, so turning this back on makes that gate inert
# almost everywhere — pads lift a thin side to target instead of the market
# standing down. The gate stays in the code and re-arms the moment padding is
# narrowed again.
PAD_TO_TARGET_GLOBAL = os.environ.get("IMM_PAD_TO_TARGET", "1") == "1"


# ---- Live-event depth gate (Jack 2026-08-31) --------------------------------
# "Remove padding on TRUMPMENTION and MAMDANIMENTION markets. If <1k on
# either side of a market, stop quoting the whole event." These events
# (speeches/streams) have start times he doesn't always know and the ticker
# date deliberately can't provide (see MENTION_LISTING_GAP_DAYS) — the one
# reliable tell that the event has gone LIVE is the book itself: the other
# makers pull their depth, and resting through that is pure adverse
# selection. For the series listed here (PREFIX match, so KXTRUMPMENTIONB
# rides the KXTRUMPMENTION entry):
#   1. pad_to_target is FORCED OFF (series_pad_to_target): a pad is
#      manufactured depth — it would blind this gate AND re-qualify exactly
#      the book we no longer want to rest in. With pads off, the per-market
#      two-sided depth gate in the quote loop re-arms for these series too.
#   2. any QUOTABLE market (external mid inside the series band — a strike
#      LISTED at the extremes is thin by nature and proves nothing) whose
#      EXTERNAL depth (book minus our own resting orders, which would
#      otherwise mask the withdrawal) is under EVENT_DEPTH_MIN_CONTRACTS on
#      EITHER side stands down its WHOLE EVENT: every sibling market is
#      cancelled and none quote. EXCEPTION (Jack 2026-09-04 "tolerate
#      one-sided scrap stacks", the SEP08 false-live): a market carrying
#      EVENT_DEPTH_STACK_CONTRACTS+ on either side is a junk-stacked book,
#      and sub-floor depth OPPOSITE a stack is that market's normal
#      lopsided shape (SEP08-AFFO: 856 yes vs 52,472 no, six days before
#      the speech), not a withdrawal — such a market never reads thin.
#      Liveness on stacked books is the tripwire's + jump confirm's job
#      (point 5: whole-side depth structurally can't see it there anyway).
#      A market that WAS two-sided and lost a touch entirely is the same
#      signal, louder — and is NOT waived by a stack.
#   3. a strike that JUMPS from inside the band to OUTSIDE it by
#      EVENT_DEPTH_JUMP_CENTS+ in one cycle (49c -> 99c: the word got said
#      and the strike settled in practice) CONFIRMS the event live — that
#      halt is PERMANENT (Jack 2026-08-31 #2: "settled strike SHOULD hold
#      an event down forever. I dont want to be quoting a live event").
#      event_live_halt is persisted; there is no resume path, and the
#      estimator refuses the whole event so nothing re-selects. The jump
#      minimum keeps a band-edge drift (89c -> 91c noise) from executing an
#      event for nothing; such a strike just stands down individually.
#   4. a thin-only halt resumes once every managed market of the event
#      reads healthy — in-band, two-sided AND at/over target — and the last
#      thin reading is EVENT_DEPTH_RESUME_SECS old. An out-of-band pin or a
#      one-sided book does NOT count as healthy: it blocks resume for as
#      long as it sits there (a settled strike holds its event down; these
#      markets die at settlement anyway, so "until settlement" IS forever).
#   5. FILL TRIPWIRE (Jack 2026-09-01, SEP01 postmortem): our own book
#      moving EVENT_FILL_HALT_CONTRACTS+ on a gated market in one cycle
#      stands the WHOLE event down (resumable), and a SECOND such burst on
#      the same event confirms it LIVE — permanent. This is the signal the
#      depth check structurally cannot give on MAMDANI-shaped books: on
#      2026-09-01 the live event was swept for 3,270 contracts over 13h
#      while total side depth never left five figures, because ~99% of it
#      was 1c/99c junk that has no reason to flee (SEP02-AFFO that evening:
#      101,699 yes contracts, 31 of them priced in-band). Fills ARE the
#      adverse selection; everything else only predicts it. Active
#      regardless of IMM_BREAKERS (the old per-market fill-burst breaker
#      is default-OFF and was never event-wide).
#   6. DATE ARM (Jack 2026-09-04: trigger "only when 1/ the date of the
#      event is not known or 2/ the date of the event is known and is
#      the current date"): every trigger above — thin, one-sided, jump
#      confirm, fill tripwire — is SUPPRESSED while the event-ticker
#      date is known and strictly in the future. A Sep 8 speech cannot
#      be live on Sep 4: SEP08 was falsely live-confirmed twice (9/2,
#      9/4) by news sweeps days early. Armed from
#      EVENT_LIVE_GATE_PREARM_H hours before midnight ET of the ticker
#      day (default 4h ~= the UTC date roll, so an evening speech dated
#      by either naming convention is covered), through the day itself,
#      and — deliberately wider than the literal spec — every day after:
#      a still-trading past-dated ticker is either a post-speech book
#      settling out or a listing-date program (the parse_event_date
#      resolution trap), and both belong gated. Unparseable date ->
#      armed. This arms TRIGGERS only: existing halts are neither
#      released nor created by it, and resume still works normally.
# Enforced in BOTH the quote loop and the candidate estimator (the
# 2026-08-05 lesson, plus its event-level twin: a thin sibling that never
# gets SELECTED is invisible to the quote loop, so without the estimator
# hook the deep strikes of a live event would keep quoting).
# KXMAMDANIMENTION REMOVED 2026-09-05 (Jack: "turn off the adverse
# selection filters on MAMDANI mention"). The 9/5 statement showed
# MAMDANI credits crashing on exactly the gated events — SEP01 (ungated)
# $12.70/mkt, SEP02 (permanently live-confirmed) $2.13, SEP03 (depth-
# halted) $1.31 with half its markets never clearing the $1 floor — while
# a clean day still pays ~$12.70, i.e. the gate, not a pool cut, drove the
# drop. Jack's call: MAMDANI quotes through liveness now (eats adverse
# fills on speech days) rather than forgoing the reward. ALL four triggers
# are prefix-gated, so dropping the prefix disables every one for MAMDANI;
# TRUMPMENTION stays protected. Re-add here or via IMM_EVENT_DEPTH_SERIES
# to restore. Existing MAMDANI halts were cleared from imm_state.json the
# same day (event_live_halt is checked series-independently, so a stale
# entry would keep an event dead even with the prefix gone).
EVENT_DEPTH_GATE_PREFIXES = tuple(
    s.strip() for s in os.environ.get(
        "IMM_EVENT_DEPTH_SERIES",
        "KXTRUMPMENTION").split(",") if s.strip())
EVENT_DEPTH_MIN_CONTRACTS = _env_float("IMM_EVENT_DEPTH_MIN", 1000)
# MUST stay > UNIVERSE_REFRESH_SECS (600): an unselected thin sibling is
# only re-observed by the estimator hook once per refresh, and the halt must
# not be able to expire between two of those observations (it would flap —
# requote the live event for a few minutes out of every refresh interval).
EVENT_DEPTH_RESUME_SECS = _env_int("IMM_EVENT_DEPTH_RESUME_SECS", 900)
# Minimum one-cycle mid move for the in-band -> out-of-band jump to count as
# the settled-strike signature. 8c catches every settlement-grade jump from
# inside the 5-90 band (worst case ~90 -> 99+) while a 1-2c edge drift stays
# a per-market band stand-down. A slow creep re-anchors prev_mid outside the
# band on its first out-of-band cycle, so it can never accumulate into a
# false confirm.
EVENT_DEPTH_JUMP_CENTS = _env_float("IMM_EVENT_DEPTH_JUMP", 8)
# Scrap-stack tolerance (point 2 exception): a side this deep is a junk
# stack nobody is pulling out of, so the opposite side escaping the floor
# is not the withdrawal signature. 10x the floor keeps every modest
# two-way trip intact (SEP02 CRYP read 966/1457 — still trips) while
# waiving the blatant stacks (52k+). 0 disables the tolerance.
EVENT_DEPTH_STACK_CONTRACTS = _env_float("IMM_EVENT_DEPTH_STACK", 10000)
# Fill tripwire (point 5 above): own-book move per cycle that stands the
# event down, and how many such bursts on one event confirm it LIVE for
# good. 15 = the old fill-burst breaker's bar, sane against routine
# one-rung crosses (a burst costs one resumable stand-down; only a repeat
# is permanent).
EVENT_FILL_HALT_CONTRACTS = _env_float("IMM_EVENT_FILL_HALT", 15)
EVENT_FILL_HALT_STRIKES = _env_int("IMM_EVENT_FILL_STRIKES", 2)
# Point 6 pre-arm: hours before midnight ET of the ticker day that the
# live triggers arm. 0 = strictly the ticker day (ET).
EVENT_LIVE_GATE_PREARM_SECS = _env_float(
    "IMM_EVENT_LIVE_GATE_PREARM_H", 4) * 3600.0


# NO-CUTOFF MENTION CLASS (Jack 2026-09-08, KXWORLDNEWSMENTION-26SEP08:
# "mention markets without a clear cutoff time, like the ABC reporters one
# today, should follow TRUMPMENTION padding/quoting behavior and stand down
# / not pad"). A mention event whose start the bot cannot derive — no
# event_start_overrides entry, no SERIES_START_ET fixed hour, no schedule
# feed, no occurrence_datetime meaningfully before expiration — has ONLY the
# midnight-ET ticker-date fallback, and midnight is not a cutoff for a
# 6:30pm broadcast. The overrides task's Phase-4 sweep assumed "no override
# -> the bot just keeps NOT quoting"; that was never a rule, only the
# accident of short listing windows dying at the $1 payout floor. WORLDNEWS
# listed at 17:45Z with ten hours to midnight and $107/day pools, cleared
# the floor, and quoted all 16 markets through the show: the first sibling
# read thin at 22:30:34Z (yes 7103 / no 0), 34 seconds after air, but the
# per-market qualify gate stood the markets down ONE AT A TIME over 29
# minutes, each only after it had already been priced to one side, while
# the survivors padded (400-700-lot 1c pads) and kept resting into the
# crash — 3,196 contracts filled in the 25 minutes after air. Under the
# TRUMPMENTION gate that first observation stands the WHOLE event down and
# no pad ever rests. So every such series joins the gate dynamically: the
# universe refresh marks it when it builds a MENTION-family meta whose
# cutoff came from the fallback, and the mark expires on its own once every
# live event of the series resolves (an override landing mid-day un-gates
# it after two refreshes). Earnings mentions are deliberately IN scope — an
# unresolved call time is exactly "no clear cutoff", and the 3x/day task
# un-gates them as it lands overrides. KXTRUMPMENTION keeps its static
# entry (its events resolve to nothing on purpose). Whole-series marking,
# not per-event, because every consumer of the gate is series-keyed; a
# resolved sibling event of a marked series rides gated for the day, which
# is the direction the 8/31 rule already chose for TRUMPMENTION-26SEP08.
# IMM_MENTION_NO_CUTOFF_GATE=0 turns the class rule off (static list stays).
MENTION_NO_CUTOFF_GATE = os.environ.get("IMM_MENTION_NO_CUTOFF_GATE", "1") == "1"
# A mark is fresh for two universe refreshes plus slack; refreshed on every
# refresh that still finds an unresolved event, so it never expires under a
# live unresolved event and clears two refreshes after the last one resolves.
MENTION_NO_CUTOFF_TTL_SECS = _env_int("IMM_MENTION_NO_CUTOFF_TTL_SECS", 1500)
_DYNAMIC_DEPTH_GATE: Dict[str, float] = {}   # series -> last marked ts


def mention_cutoff_is_clear(series: str, resolved: Optional[datetime],
                            occurrence: Optional[datetime],
                            expected_expiration: Optional[datetime]) -> bool:
    """False when a MENTION-family event has no derivable start and would be
    quoting on the midnight-of-ticker-date fallback alone. Non-mention
    series are always 'clear' (the rule is scoped like the suffix allowlist
    that admits these families). Mirrors trade_cutoff_utc's occurrence test
    exactly: an occurrence that is not >60min before expiration is a
    settlement stamp, not an event start."""
    if not any(series.endswith(suf) for suf in ALLOW_SERIES_SUFFIXES):
        return True
    if resolved is not None:
        return True
    if occurrence is not None and (
            expected_expiration is None
            or occurrence < expected_expiration - timedelta(minutes=60)):
        return True
    return False


def mark_no_cutoff_mention(series: str, now_ts: float) -> bool:
    """Put `series` on the live-event depth gate for MENTION_NO_CUTOFF_TTL_SECS
    (refreshing an existing mark). Returns True when this is a NEW mark, so
    the caller can log the transition once rather than every refresh."""
    if not MENTION_NO_CUTOFF_GATE:
        return False
    if series.startswith(tuple(EVENT_DEPTH_GATE_PREFIXES)):
        return False     # already gated statically; don't re-attribute it
    fresh = _DYNAMIC_DEPTH_GATE.get(series)
    _DYNAMIC_DEPTH_GATE[series] = now_ts
    return fresh is None or now_ts - fresh > MENTION_NO_CUTOFF_TTL_SECS


def dynamic_depth_gated_series(now_ts: Optional[float] = None) -> Set[str]:
    now_ts = time.time() if now_ts is None else now_ts
    return {s for s, ts in _DYNAMIC_DEPTH_GATE.items()
            if now_ts - ts <= MENTION_NO_CUTOFF_TTL_SECS}


def series_event_depth_gated(series: str) -> bool:
    if series.startswith(tuple(EVENT_DEPTH_GATE_PREFIXES)):
        return True
    if not MENTION_NO_CUTOFF_GATE:
        return False
    ts = _DYNAMIC_DEPTH_GATE.get(series)
    return ts is not None and time.time() - ts <= MENTION_NO_CUTOFF_TTL_SECS


def event_live_gate_armed(event_ticker: str, now_ts: float) -> bool:
    """Point 6 (Jack 2026-09-04): live stand-down triggers fire only when
    the event-ticker date is unknown (parse -> None) or now is past
    midnight ET of that date minus the pre-arm. Known-future -> False."""
    d = parse_event_date(event_ticker)
    if d is None:
        return True
    return now_ts >= d.timestamp() - EVENT_LIVE_GATE_PREARM_SECS


