                                                "KXTRUEV:3,"
                                                # Carbon Arc *CC / *ADS /
                                                # *POS: uncapped since
                                                # 2026-10-01 (the
                                                # _CA_FAMILY spec below)
                                                # data center counts
                                                # (2026-10-01, "max 3
                                                # markets per event")
                                                "*DATACENTERS:3,"
                                                # exact: KXART is a prefix
                                                # of 20 unrelated series
                                                "=KXART:3,"
