def _git_sha() -> str:
    """Short HEAD sha, best-effort. Never raises, never blocks startup."""
    import subprocess
    try:
        out = subprocess.run(
            ["git", "-C", os.path.dirname(_SOURCE_PATH) or ".",
             "rev-parse", "--short", "HEAD"],
            capture_output=True, text=True, timeout=5)
        return (out.stdout or "").strip() or "unknown"
    except Exception:
        return "unknown"


def _build_config() -> Tuple[Dict[str, str], str]:
    """Snapshot the effective configuration and digest it.

    Secrets are excluded by name, not by value: this dict is written to disk
    in full, and KALSHI_* legitimately holds key material."""
    import hashlib
    # FEED_URL: a data-feed URL can carry its key in the query string
    secret = ("KEY", "SECRET", "TOKEN", "PASSWORD", "PRIVATE", "FEED_URL")
    cfg: Dict[str, str] = {}
    for k, v in os.environ.items():
        if not (k.startswith("IMM_") or k.startswith("KALSHI_")):
            continue
        cfg[k] = "<redacted>" if any(s in k.upper() for s in secret) else str(v)
    g = globals()
    for name in _CONFIG_CODE_KNOBS:
        if name in g:
            cfg[f"code:{name}"] = str(g[name])
    digest = hashlib.sha1(
        json.dumps(cfg, sort_keys=True).encode("utf-8")).hexdigest()[:8]
    return cfg, digest
_HOURLY_TEMP_RE = re.compile(r"^KXTEMP[A-Z]+H-")


def code_change_exit_due(selected, now_utc: datetime,
                         current_mtime: Optional[float] = None,
                         now_ts: Optional[float] = None) -> bool:
    """True when the on-disk source differs from the imported one and this
    instant is safe to restart in. `selected` is the live selection (ticker
    -> meta; only the tickers are read) — hourly-temp membership is judged
    on the same ^KXTEMP<CITY>H- shape restart_imm.ps1 keys on. The
    current_mtime/now_ts params exist for tests."""
    if not EXIT_ON_CODE_CHANGE:
        return False
    if current_mtime is None:
        try:
            current_mtime = os.path.getmtime(_SOURCE_PATH)
        except OSError:
            return False
    if current_mtime == _SOURCE_MTIME:
        return False
    if (now_ts if now_ts is not None else time.time()) - current_mtime < 60:
        return False
    minute = now_utc.astimezone(ET).minute
    if minute >= 50 or minute <= 5:
        return True
    return not any(_HOURLY_TEMP_RE.match(str(t)) for t in (selected or ()))

